using System;
using System.Collections.Generic;

public class ListDemo
{
    public static void Main()
    {
        // Empty list
        List<string> names = new List<string>();

        // Add items one at a time
        names.Add("Alice");
        names.Add("Bob");
        names.Add("Charlie");

        // Initialize with values
        List<int> scores = new List<int> { 95, 87, 72, 91 };

        // Index access — zero-based, same as arrays
        string first = names[0];        // "Alice"
        names[1] = "Barbara";          // Replaces "Bob"

        // Count property
        int totalNames = names.Count;    // 3

        // Contains — checks for presence
        bool hasAlice = names.Contains("Alice"); // true

        // Remove by value (returns true if found and removed)
        bool removed = names.Remove("Barbara");  // true

        // RemoveAt — remove by index
        names.RemoveAt(0);              // Removes "Alice"

        // Insert — add at a specific position
        names.Insert(1, "David");

        // Iterate with foreach
        foreach (string name in names)
        {
            Console.WriteLine(name);
        }

        // Convert to array
        string[] nameArray = names.ToArray();
    }
}

using System;
using System.Collections.Generic;

public class DictionaryDemo
{
    public static void Main()
    {
        // Mapping student IDs to names
        Dictionary<int, string> students = new Dictionary<int, string>
        {
            { 101, "Alice" },
            { 102, "Bob" },
            { 103, "Charlie" }
        };

        // Indexer — throws KeyNotFoundException if key missing
        string name = students[102];   // "Bob"

        // Safe access with TryGetValue — preferred in production
        if (students.TryGetValue(104, out string? result))
        {
            Console.WriteLine(result);
        }
        else
        {
            Console.WriteLine("Student 104 not found.");
        }

        // ContainsKey — check before accessing by indexer
        if (students.ContainsKey(101))
        {
            Console.WriteLine(students[101]); // "Alice"
        }

        // Add or update
        students[104] = "Diana";      // Add (or overwrite)
        students.Add(105, "Eve");      // Add only — throws if key exists

        // Remove by key
        students.Remove(103);            // Removes Charlie

        // Iterate over all pairs
        foreach (KeyValuePair<int, string> entry in students)
        {
            Console.WriteLine($"ID: {entry.Key}, Name: {entry.Value}");
        }

        // Get just the keys or values
        List<int> allIds = new List<int>(students.Keys);
        List<string> allNames = new List<string>(students.Values);

        Console.WriteLine($"Total students: {students.Count}");
    }
}

using System;
using System.Collections.Generic;

public class HashSetDemo
{
    public static void Main()
    {
        HashSet<string> uniqueTags = new HashSet<string>();

        // Add returns false if the item already exists
        uniqueTags.Add("csharp");   // true — added
        uniqueTags.Add("dotnet");   // true — added
        uniqueTags.Add("csharp");   // false — duplicate ignored

        // Contains — O(1) membership check
        bool isTagged = uniqueTags.Contains("dotnet"); // true

        // UnionWith adds all items from another set (deduplicating)
        HashSet<string> moreTags = new() { "web", "api", "csharp" };
        uniqueTags.UnionWith(moreTags);
        // uniqueTags now has: csharp, dotnet, web, api

        // Remove
        uniqueTags.Remove("web");

        foreach (string tag in uniqueTags)
        {
            Console.WriteLine(tag);
        }
    }
}

using System;
using System.Collections.Generic;

public class QueueDemo
{
    public static void Main()
    {
        Queue<string> printQueue = new Queue<string>();

        // Enqueue — add to the end of the line
        printQueue.Enqueue("Report.pdf");
        printQueue.Enqueue("Invoice.docx");
        printQueue.Enqueue("Photo.jpg");

        // Peek — see who is next without removing them
        string nextJob = printQueue.Peek(); // "Report.pdf"

        // Dequeue — remove and return the front item
        while (printQueue.Count > 0)
        {
            string job = printQueue.Dequeue();
            Console.WriteLine($"Printing: {job}");
        }
        // Prints: Report.pdf, Invoice.docx, Photo.jpg

        // Count is now 0
    }
}

using System;
using System.Collections.Generic;

public class UndoDemo
{
    static Stack<string> undoStack = new Stack<string>();

    public static void Main()
    {
        // Simulate user typing — each action is pushed
        TypeText("Hello");
        TypeText(" World");
        TypeText("!");

        // Undo the last action
        Undo(); // Removes "!"
        Undo(); // Removes " World"
    }

    static void TypeText(string text)
    {
        undoStack.Push(text);
        Console.WriteLine($"Typed: {text}");
    }

    static void Undo()
    {
        if (undoStack.Count > 0)
        {
            string removed = undoStack.Pop();
            Console.WriteLine($"Undid: {removed}");
        }
    }
}

